DECLARE
  l_failures      PLS_INTEGER := 0;
  l_existing_dept NUMBER;
  l_no_match_dept NUMBER;
  l_expected      NUMBER;
  l_actual        NUMBER;

  PROCEDURE check_result(
    p_name     IN VARCHAR2,
    p_expected IN NUMBER,
    p_actual   IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_name ||
        ', expected=' || NVL(TO_CHAR(p_expected), 'NULL') ||
        ', actual=' || NVL(TO_CHAR(p_actual), 'NULL')
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_name ||
        ', expected=' || NVL(TO_CHAR(p_expected), 'NULL') ||
        ', actual=' || NVL(TO_CHAR(p_actual), 'NULL')
      );
      l_failures := l_failures + 1;
    END IF;
  END check_result;
BEGIN
  SAVEPOINT test_headcount_sp;

  -- Find a non-NULL department_id that should match at least one row.
  SELECT MIN(department_id)
    INTO l_existing_dept
    FROM HARNESS_APP.employees
   WHERE department_id IS NOT NULL;

  IF l_existing_dept IS NOT NULL THEN
    -- Expected value computed independently using the same comparison as the function.
    SELECT COUNT(*)
      INTO l_expected
      FROM HARNESS_APP.employees
     WHERE department_id = l_existing_dept;

    l_actual := HARNESS_APP.headcount(l_existing_dept);
    check_result(
      'headcount(existing non-NULL department_id)',
      l_expected,
      l_actual
    );

    -- Pick a non-NULL value that cannot occur because it is below the minimum
    -- non-NULL department_id. Confirm independently that it matches no rows.
    l_no_match_dept := l_existing_dept - 1;

    SELECT COUNT(*)
      INTO l_expected
      FROM HARNESS_APP.employees
     WHERE department_id = l_no_match_dept;

    IF l_expected <> 0 THEN
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: setup for no-match non-NULL department_id, expected=0, actual=' ||
        TO_CHAR(l_expected)
      );
      l_failures := l_failures + 1;
    ELSE
      l_actual := HARNESS_APP.headcount(l_no_match_dept);
      check_result(
        'headcount(non-NULL department_id matching no row)',
        0,
        l_actual
      );
    END IF;
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: setup for existing non-NULL department_id, reason=no non-NULL department_id found in HARNESS_APP.employees'
    );
    l_failures := l_failures + 1;

    DBMS_OUTPUT.PUT_LINE(
      'FAIL: setup for no-match non-NULL department_id, reason=no non-NULL department_id available to derive a value below the minimum'
    );
    l_failures := l_failures + 1;
  END IF;

  -- NULL argument case. The function compares with =, so WHERE department_id = NULL
  -- matches no rows, even if rows have department_id IS NULL.
  l_actual := HARNESS_APP.headcount(NULL);
  check_result(
    'headcount(NULL department_id)',
    0,
    l_actual
  );

  DBMS_OUTPUT.PUT_LINE('Summary: failures=' || TO_CHAR(l_failures));

  ROLLBACK TO test_headcount_sp;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(-20999, 'headcount test block failed with ' || l_failures || ' failure(s).');
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_headcount_sp;
    RAISE;
END;
```

The block calls the selected unit as `HARNESS_APP.headcount` rather than copying its code. It checks three cases:

- A non-NULL `department_id` that exists in `HARNESS_APP.employees`, using an independently computed `COUNT(*)` as the expected value. If no such row is found, the setup check prints `FAIL` and counts as a failure.
- A non-NULL `department_id` that should match no row, derived as one less than the minimum non-NULL `department_id`. The block independently confirms that this value matches zero rows before calling the function. If no suitable existing value is available, the setup check prints `FAIL` and counts as a failure.
- A `NULL` argument. Because the function uses `WHERE department_id = p_department_id`, the expected result is `0`, not a count of rows where `department_id IS NULL`.

The block starts with `SAVEPOINT test_headcount_sp` and ends with `ROLLBACK TO test_headcount_sp`, so it does not commit. If any check fails, it raises an application error after rolling back to the savepoint. The exception section prints unexpected errors, rolls back to the savepoint, and re-raises. I have not run this block.

